// The command line, built from manifest.json. Generated by anything-anything from anything.toml.
import { parseArgs } from "node:util";
import { registry } from "./commands/index.ts";
import manifest from "./manifest.json" with { type: "json" };
import { serve } from "./mcp.ts";

export type Kind = "string" | "path" | "int" | "float" | "bool" | "list";
export type Arg = { name: string; key: string; kind: Kind; help: string; positional: boolean; required: boolean; default: unknown };
export type CommandDef = { name: string; module: string; about: string; tool: string; args: Arg[] };

export const commands = manifest.commands as CommandDef[];

function convert(arg: Arg, raw: string): unknown {
  if (arg.kind === "int" || arg.kind === "float") {
    const n = arg.kind === "int" ? Number.parseInt(raw, 10) : Number.parseFloat(raw);
    if (Number.isNaN(n) || (arg.kind === "int" && !/^-?\d+$/.test(raw))) throw new Error(`--${arg.name}: ${raw} isn't a number`);
    return n;
  }
  if (arg.kind === "list") return raw.split(",").map((s) => s.trim()).filter(Boolean);
  return raw;
}

/** A command's arguments from a dict (an MCP call): defaults filled in, unknown keys refused. */
export function argsFrom(command: CommandDef, values: Record<string, unknown>): Record<string, unknown> {
  const extra = Object.keys(values).filter((k) => !command.args.some((a) => a.key === k));
  if (extra.length) throw new Error(`unknown argument(s): ${extra.join(", ")}`);
  const out: Record<string, unknown> = {};
  for (const a of command.args) {
    if (a.key in values) out[a.key] = values[a.key];
    else if (a.required) throw new Error(`${a.key} is required`);
    else if (a.default !== null) out[a.key] = a.default;
  }
  return out;
}

function usage(c: CommandDef): string {
  const parts = c.args.map((a) => {
    if (a.positional) return a.kind === "list" ? `[${a.name}...]` : a.required ? `<${a.name}>` : `[${a.name}]`;
    if (a.kind === "bool") return `[--${a.name}]`;
    return a.required ? `--${a.name} <${a.name}>` : `[--${a.name} <${a.name}>]`;
  });
  const lines = [`${manifest.name} ${c.name} ${parts.join(" ")}`, "", c.about, ""];
  for (const a of c.args) lines.push(`  ${a.positional ? a.name : `--${a.name}`}  ${a.help}`);
  lines.push("  --json  print the result as JSON");
  return lines.join("\n");
}

function help(): string {
  const width = Math.max(...commands.map((c) => c.name.length), 3);
  const lines = [`${manifest.name} ${manifest.version}: ${manifest.pitch}`, "", "commands:"];
  for (const c of commands) lines.push(`  ${c.name.padEnd(width)}  ${c.about}`);
  lines.push(`  ${"mcp".padEnd(width)}  run as an MCP server on stdio (Claude Code, Codex, Cursor, ...)`);
  return lines.join("\n");
}

function parse(c: CommandDef, argv: string[]): { args: Record<string, unknown>; json: boolean; help: boolean } {
  const options: Record<string, { type: "string" | "boolean"; short?: string }> = { json: { type: "boolean" }, help: { type: "boolean", short: "h" } };
  for (const a of c.args) if (!a.positional) options[a.name] = { type: a.kind === "bool" ? "boolean" : "string" };
  const { values, positionals } = parseArgs({ args: argv, options, allowPositionals: true, strict: true });
  const args: Record<string, unknown> = {};
  let rest = [...positionals];
  for (const a of c.args) {
    if (a.positional) {
      if (a.kind === "list") {
        args[a.key] = rest.length ? rest : a.default;
        rest = [];
      } else if (rest.length) {
        args[a.key] = convert(a, rest.shift() as string);
      } else if (a.required && !values.help) {
        throw new Error(`<${a.name}> is required\n\n${usage(c)}`);
      } else if (a.default !== null) {
        args[a.key] = a.default;
      }
      continue;
    }
    const v = values[a.name];
    if (a.kind === "bool") args[a.key] = v === true;
    else if (typeof v === "string") args[a.key] = convert(a, v);
    else if (a.required && !values.help) throw new Error(`--${a.name} is required\n\n${usage(c)}`);
    else if (a.default !== null) args[a.key] = a.default;
  }
  if (rest.length) throw new Error(`unexpected ${rest.join(" ")}\n\n${usage(c)}`);
  return { args, json: values.json === true, help: values.help === true };
}

export async function main(argv: string[]): Promise<number> {
  const [name, ...rest] = argv;
  if (!name || name === "--help" || name === "-h") {
    console.log(help());
    return name ? 0 : 2;
  }
  if (name === "--version" || name === "-V") {
    console.log(`${manifest.name} ${manifest.version}`);
    return 0;
  }
  if (name === "mcp") {
    await serve();
    return 0;
  }
  const command = commands.find((c) => c.name === name);
  const run = command && registry[command.module];
  if (!command || !run) {
    console.error(`✗ unknown command ${name}\n\n${help()}`);
    return 2;
  }
  try {
    const parsed = parse(command, rest);
    if (parsed.help) {
      console.log(usage(command));
      return 0;
    }
    const out = await run(parsed.args);
    out.print(parsed.json);
    return out.exit;
  } catch (e) {
    console.error(`✗ ${e instanceof Error ? e.message : String(e)}`);
    return 1;
  }
}
